// Create a Delaunay triangulation
    typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
    typedef CGAL::Delaunay_triangulation_2<K> DT;
    DT dt;
    for (const auto& p : points) {
        dt.insert(p);
    }

    // Compute the Voronoi diagram as the dual of the Delaunay triangulation
    std::vector<std::vector<Point2d>> voronoiCells;
    for (auto it = dt.finite_faces_begin(); it != dt.finite_faces_end(); ++it) {
        std::vector<Point2d> cell;
        auto circ = it->incident_halfedges();
        do {
            auto he = circ;
            auto v = dt.dual(he);
            cell.push_back(v);
        } while (++circ != it->incident_halfedges());
        voronoiCells.push_back(cell);
    }
    return voronoiCells;

